/**
 * Loads the marginal grid factors SEI fills in to
 * data/sei-marginal-factors.template.json and attaches them to the matching
 * GRID_REGIONS entry as `marginal`.
 *
 * grids.ts is generated by scripts/update-grid-data.js, so the marginal data
 * lives in the template instead and is merged here. Regenerating grids.ts
 * therefore never drops it. The package exports the merged GRID_REGIONS from
 * this module; code in src/ that needs marginal factors should import it from
 * here, not from ./grids.js.
 */

import template from "../data/sei-marginal-factors.template.json" with { type: "json" };
import { GRID_REGIONS as AVERAGE_GRID_REGIONS } from "./grids.js";
import type { GridRegion, MarginalIntensity } from "./types.js";

/** The marginal fields of one region in the SEI template. */
export interface MarginalTemplateEntry {
  marginal?: number | null;
  marginalHourly?: number[] | null;
  marginalSource?: string | null;
  marginalYear?: number | null;
}

const isNonNegative = (v: unknown): v is number =>
  typeof v === "number" && Number.isFinite(v) && v >= 0;

/**
 * Turns one template entry into a MarginalIntensity. An empty entry gives
 * neither a factor nor problems. A filled-in entry needs a value, a source and
 * a year; an hourly profile, when given, needs 24 values (hour 0-23).
 */
export function parseMarginalEntry(entry: MarginalTemplateEntry): {
  marginal?: MarginalIntensity;
  problems: string[];
} {
  const problems: string[] = [];
  const { marginal, marginalHourly, marginalSource, marginalYear } = entry;

  if (marginal == null) {
    if (marginalHourly != null || marginalSource != null || marginalYear != null) {
      problems.push("marginalHourly, marginalSource or marginalYear is set but marginal is empty");
    }
    return { problems };
  }

  if (!isNonNegative(marginal)) problems.push("marginal must be a number >= 0");
  if (typeof marginalSource !== "string" || marginalSource.trim() === "") {
    problems.push("marginalSource is required when marginal is set");
  }
  if (typeof marginalYear !== "number" || !Number.isInteger(marginalYear)) {
    problems.push("marginalYear is required when marginal is set");
  }
  if (marginalHourly != null) {
    if (!Array.isArray(marginalHourly) || marginalHourly.length !== 24) {
      problems.push("marginalHourly must have 24 entries (hour 0-23)");
    } else if (!marginalHourly.every(isNonNegative)) {
      problems.push("marginalHourly entries must be numbers >= 0");
    }
  }
  if (problems.length > 0) return { problems };

  return {
    marginal: {
      gPerKwh: marginal,
      ...(marginalHourly != null && { hourly: [...marginalHourly] }),
      source: marginalSource as string,
      year: marginalYear as number,
    },
    problems,
  };
}

/**
 * Returns a copy of `regions` with each complete template entry attached as
 * `marginal`. Regions without a complete entry are returned unchanged, so the
 * calculator keeps falling back to average accounting for them. Incomplete
 * entries are skipped silently here; marginal-factors.test.ts fails on them.
 */
export function withMarginalFactors(
  regions: Record<string, GridRegion>,
  entries: Record<string, MarginalTemplateEntry>,
): Record<string, GridRegion> {
  return Object.fromEntries(
    Object.entries(regions).map(([id, region]) => {
      const entry = entries[id];
      const marginal = entry ? parseMarginalEntry(entry).marginal : undefined;
      return [id, marginal ? { ...region, marginal } : region];
    }),
  );
}

/** GRID_REGIONS with SEI's marginal factors attached where they have been filled in. */
export const GRID_REGIONS: Record<string, GridRegion> = withMarginalFactors(
  AVERAGE_GRID_REGIONS,
  template.regions as Record<string, MarginalTemplateEntry>,
);
